"""Build/check the single-file Git Bash launcher from the reviewed tool sources."""
from pathlib import Path
import argparse

ROOT = Path(__file__).resolve().parent
TARGET = ROOT.parents[1] / "resources/tools/build-helpy-cache.sh"
HEADER = '''#!/usr/bin/env bash
# Optional RuneSchema author tool. Generated by tools/helpy-cache/package.py.
# Requires Windows + Git Bash + .NET 10 SDK. No game/PAK/save mutation.
set -euo pipefail
command -v dotnet >/dev/null || { echo "Install the .NET 10 SDK first." >&2; exit 1; }
command -v cygpath >/dev/null || { echo "Use Git Bash on Windows for this release." >&2; exit 1; }
script_folder="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd -P)"
stage="$(mktemp -d "${TMPDIR:-/tmp}/runeschema-helpy-cache.XXXXXXXX")"
cleanup() {
    case "$stage" in "${TMPDIR:-/tmp}"/runeschema-helpy-cache.*) rm -rf -- "$stage" ;; esac
}
trap cleanup EXIT
'''
FOOTER = '''project="$(cygpath -w "$stage/HelpyCache.csproj")"
dotnet restore "$project" --locked-mode --verbosity quiet
dotnet build "$project" --no-restore --configuration Release --verbosity quiet
dotnet "$(cygpath -w "$stage/bin/Release/net10.0/HelpyCache.dll")" --folder "$(cygpath -w "$script_folder")" "$@"
'''

def render():
    result = HEADER
    for name in ("HelpyCache.csproj", "Program.cs", "packages.lock.json"):
        delimiter = "RUNESCHEMA_" + name.replace(".", "_").upper()
        source = (ROOT / name).read_text(encoding="utf-8")
        assert delimiter not in source.splitlines()
        result += f'cat > "$stage/{name}" <<\'{delimiter}\'\n{source.rstrip()}\n{delimiter}\n'
    return result + FOOTER

if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    text = render()
    if args.check:
        assert TARGET.read_text(encoding="utf-8") == text, "Regenerate the drop-in script"
        print("Drop-in script matches the reviewed sources and dependency lock.")
    else:
        TARGET.parent.mkdir(parents=True, exist_ok=True)
        TARGET.write_text(text, encoding="utf-8", newline="\n")
        print(TARGET)
